import { errorResponse } from '#lib/server/api';

export type Employee = NonNullable<App.Locals['employee']>;

export const ROLE_NHAN_VIEN = 'NHAN_VIEN';
export const ROLE_QUAN_LY = 'QUAN_LY';

export function unauthenticated(): Response {
  return errorResponse(401, 'UNAUTHENTICATED', 'Vui lòng đăng nhập');
}

export function forbiddenRole(): Response {
  return errorResponse(403, 'FORBIDDEN_ROLE', 'Bạn không có quyền thực hiện thao tác này');
}
